CREATE OR REPLACE FUNCTION public.reserve_customer_order(_user uuid,_address uuid,_items jsonb,_key uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o uuid; a public.addresses; s public.shipping_rules; p public.products; i jsonb; qty integer; sub integer:=0; tax integer:=0; item_id uuid; supplier uuid; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(_user::text,0)); SELECT id INTO o FROM public.orders WHERE user_id=_user AND idempotency_key=_key; IF FOUND THEN RETURN o; END IF; IF jsonb_typeof(_items)<>'array' OR jsonb_array_length(_items) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid cart'; END IF; IF (SELECT count(DISTINCT value->>'productId') FROM jsonb_array_elements(_items))<>jsonb_array_length(_items) THEN RAISE EXCEPTION 'Duplicate cart item'; END IF; SELECT * INTO a FROM public.addresses WHERE id=_address AND user_id=_user; IF NOT FOUND THEN RAISE EXCEPTION 'Address unavailable'; END IF; SELECT * INTO s FROM public.shipping_rules WHERE pincode=a.pincode AND active; IF NOT FOUND THEN RAISE EXCEPTION 'Delivery not configured'; END IF; INSERT INTO public.orders(user_id,total_paise,address_snapshot,idempotency_key,reservation_expires_at,shipping_paise) VALUES(_user,0,to_jsonb(a)-'user_id',_key,now()+interval '15 minutes',s.fee_paise) RETURNING id INTO o; FOR i IN SELECT value FROM jsonb_array_elements(_items) ORDER BY value->>'productId' LOOP qty:=(i->>'quantity')::integer; IF qty NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'Invalid quantity'; END IF; SELECT * INTO p FROM public.products WHERE id=i->>'productId' AND status='active' FOR UPDATE; IF NOT FOUND OR p.is_demo OR p.tax_bps IS NULL OR p.tax_bps NOT BETWEEN 0 AND 10000 THEN RAISE EXCEPTION 'Product not approved for sale'; END IF; supplier:=NULL; IF p.fulfillment_model='OWN_INVENTORY' THEN UPDATE public.inventory SET reserved=reserved+qty WHERE product_id=p.id AND quantity-reserved>=qty; IF NOT FOUND THEN RAISE EXCEPTION 'Insufficient stock'; END IF; ELSE SELECT sp.supplier_id INTO supplier FROM public.supplier_products sp JOIN public.suppliers ss ON ss.id=sp.supplier_id WHERE sp.product_id=p.id AND sp.available AND ss.approved AND ss.manual_fulfillment ORDER BY sp.id LIMIT 1; IF NOT FOUND THEN RAISE EXCEPTION 'Supplier unavailable'; END IF; END IF; sub:=sub+p.price_paise*qty; tax:=tax+CASE WHEN p.tax_inclusive THEN 0 ELSE round(p.price_paise*qty*p.tax_bps/10000.0)::integer END; INSERT INTO public.order_items(order_id,product_id,name,sku,quantity,unit_price_paise,tax_bps,return_days,fulfillment_model) VALUES(o,p.id,p.name,p.sku,qty,p.price_paise,p.tax_bps,p.return_days,p.fulfillment_model) RETURNING id INTO item_id; INSERT INTO public.fulfillments(order_id,item_id,supplier_id) VALUES(o,item_id,supplier); END LOOP; UPDATE public.orders SET subtotal_paise=sub,tax_paise=tax,total_paise=sub+tax+s.fee_paise WHERE id=o; RETURN o; END $$;
REVOKE ALL ON FUNCTION public.reserve_customer_order(uuid,uuid,jsonb,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reserve_customer_order(uuid,uuid,jsonb,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.release_unpaid_order(_order uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; BEGIN SELECT * INTO o FROM public.orders WHERE id=_order FOR UPDATE; IF NOT FOUND OR o.payment_status='paid' OR o.status='cancelled' THEN RETURN; END IF; IF EXISTS(SELECT 1 FROM public.payments WHERE order_id=_order) THEN RAISE EXCEPTION 'Reconcile gateway before releasing a payment-linked order'; END IF; UPDATE public.inventory inv SET reserved=inv.reserved-oi.quantity FROM public.order_items oi WHERE oi.order_id=o.id AND oi.product_id=inv.product_id AND oi.fulfillment_model='OWN_INVENTORY'; UPDATE public.orders SET status='cancelled',payment_status='failed' WHERE id=o.id; UPDATE public.fulfillments SET status='cancelled',updated_at=now() WHERE order_id=o.id; END $$;
REVOKE ALL ON FUNCTION public.release_unpaid_order(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.release_unpaid_order(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.record_captured_payment(_event text,_provider_order text,_payment text,_amount integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pay public.payments; o public.orders; BEGIN SELECT * INTO pay FROM public.payments WHERE provider_order_id=_provider_order FOR UPDATE; IF NOT FOUND OR pay.amount_paise<>_amount THEN RAISE EXCEPTION 'Payment reconciliation required'; END IF; SELECT * INTO o FROM public.orders WHERE id=pay.order_id FOR UPDATE; IF o.status='cancelled' THEN RAISE EXCEPTION 'Cancelled order requires refund reconciliation'; END IF; INSERT INTO public.payment_webhook_events(id,event_type,result) VALUES(_event,'payment.captured','accepted') ON CONFLICT DO NOTHING; IF NOT FOUND THEN RETURN; END IF; IF pay.status='paid' THEN IF pay.provider_payment_id<>_payment THEN RAISE EXCEPTION 'Unexpected duplicate payment'; END IF; RETURN; END IF; UPDATE public.inventory inv SET quantity=inv.quantity-oi.quantity,reserved=inv.reserved-oi.quantity FROM public.order_items oi WHERE oi.order_id=o.id AND oi.product_id=inv.product_id AND oi.fulfillment_model='OWN_INVENTORY'; UPDATE public.payments SET status='paid',provider_payment_id=_payment WHERE id=pay.id; UPDATE public.orders SET payment_status='paid',status='confirmed' WHERE id=o.id; UPDATE public.fulfillments SET status=CASE WHEN supplier_id IS NULL THEN 'processing' ELSE 'awaiting_supplier_fulfillment' END,updated_at=now() WHERE order_id=o.id; END $$;
REVOKE ALL ON FUNCTION public.record_captured_payment(text,text,text,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.record_captured_payment(text,text,text,integer) TO service_role;
CREATE OR REPLACE FUNCTION public.update_fulfillment(_id uuid,_status text,_carrier text,_tracking text,_url text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f public.fulfillments; BEGIN IF NOT public.staff_has_role(ARRAY['owner','admin','operations']) THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO f FROM public.fulfillments WHERE id=_id FOR UPDATE; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.orders WHERE id=f.order_id AND payment_status='paid') THEN RAISE EXCEPTION 'Paid fulfillment required'; END IF; IF NOT ((f.status IN ('processing','awaiting_supplier_fulfillment') AND _status='shipped') OR (f.status='shipped' AND _status IN ('out_for_delivery','delivered')) OR (f.status='out_for_delivery' AND _status='delivered')) THEN RAISE EXCEPTION 'Invalid fulfillment transition'; END IF; IF _status='shipped' AND (length(trim(_carrier))=0 OR length(trim(_tracking))=0 OR (_url<>'' AND _url NOT LIKE 'https://%')) THEN RAISE EXCEPTION 'Carrier and tracking required'; END IF; UPDATE public.fulfillments SET status=_status,carrier=nullif(_carrier,''),tracking_number=nullif(_tracking,''),tracking_url=nullif(_url,''),updated_at=now() WHERE id=f.id; IF NOT EXISTS(SELECT 1 FROM public.fulfillments WHERE order_id=f.order_id AND status<>'delivered') THEN UPDATE public.orders SET status='delivered',delivered_at=now() WHERE id=f.order_id; ELSIF NOT EXISTS(SELECT 1 FROM public.fulfillments WHERE order_id=f.order_id AND status NOT IN ('shipped','out_for_delivery','delivered')) THEN UPDATE public.orders SET status='shipped' WHERE id=f.order_id; END IF; INSERT INTO public.audit_logs(actor_id,action,entity_id,details) VALUES(auth.uid(),'fulfillment:'||_status,f.id::text,jsonb_build_object('order_id',f.order_id)); END $$;
REVOKE ALL ON FUNCTION public.update_fulfillment(uuid,text,text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.update_fulfillment(uuid,text,text,text,text) TO authenticated;